-- BRANCH_PROTECTION conf_json 增量更新（5 层递进展示口径 v3；2026-10-15 两次文案修订）
-- 执行方式：直接对 Doris 运行；生效时间：后端 5 分钟 TTL 缓存过期后
UPDATE internal.openlibing.dm_rd_efc_security_metric_detail_conf
SET conf_json = '{"rule":{"brief":"指标定义采用 5 层递进计分（3+3+2+1+1，上一层全部满足才进入下一层）。结合平台实际管控现状映射：第 1-3 层由 GitCode 平台默认分支保护满足（基线 8 分）；第 4-5 层考察 rebot.yaml 是否配置 2 名及以上审查者（lgtm_need_num=2）并真正落实（+2 分）。","formula":"总分 10 分 = 第 1 层 3 分 + 第 2 层 3 分 + 第 3 层 2 分 + 第 4 层 1 分 + 第 5 层 1 分。落地映射：第 1-3 层由平台默认分支保护满足（基线 8 分）；第 4-5 层需配置 .infra_self_service/rebot.yaml（lgtm_need_num=2）且近 30 个已合入 PR 均有 2 名及以上审查者（剔除机器人和 PR 作者）认可，得 +2 分；第 5 层与第 4 层同判，第 4 层不满足时第 5 层不再判定。无中间分：8 分或 10 分。","conditions":[{"label":"第 1 层（3 分）","value":"禁止删除分支、禁止强制推送"},{"label":"第 2 层（3 分）","value":"要求 1 名以上审查者、要求通过 PR 合并、要求分支保持最新、要求最近推送审批"},{"label":"第 3 层（2 分）","value":"要求 CI 状态检查通过"},{"label":"第 4 层（1 分）","value":"要求 2 名以上审查者、要求 CODEOWNERS 审查"},{"label":"第 5 层（1 分）","value":"取消过时审查、管理员强制执行保护规则"}],"naCondition":"无，本指标恒有得分。","notes":["lgtm_need_num 取其他值（1/3/…）不触发 2 名及以上审查者检查，按默认 8 分","第 4 层不满足时第 5 层显示「未评估」（层级递进不再判定），不是不满足、也不是扣分项"]},"definition":{"brief":"衡量仓库受保护分支的管控强度：指标定义 5 层递进——禁止删除/强推、基础评审要求、CI 门禁、双人审查、取消过时审查/管理员强制执行；GitCode 平台默认管控覆盖前 3 层，后 2 层考察 rebot.yaml 2 名及以上审查者配置与落实。","purpose":"分支保护防止绕过评审直接 push；多人审批保证关键代码至少经两人把关，降低单点失误与恶意合入的风险。","details":[{"label":"数据来源","value":"GitCode 平台默认分支保护（平台级）+ .infra_self_service/rebot.yaml 配置扫描 + 近 30 个已合入 PR 的 /lgtm 评论"},{"label":"统计口径","value":"近 30 个已合入 PR 的 /lgtm 评论（剔除机器人和 PR 作者）"},{"label":"评分结构","value":"5 层递进 3+3+2+1+1：第 1-3 层映射平台默认基线 8 分，第 4-5 层映射 rebot.yaml 2 名及以上审查者增强 2 分"}],"notes":[]},"summary":[{"key":"tiers","label":"已满足层级","value":"#map:$pr_lgtm_pass:1:5 / 5,*:3 / 5","level":"#map:$pr_lgtm_pass:1:success,*:"},{"key":"need","label":"评审人数要求","value":"#ifnull:$lgtm_need_num:1","level":"#map:$has_rebot_yaml:1:success,0:na,*:"},{"key":"prpass","label":"审查者人数检查","value":"#map:$pr_lgtm_pass:1:全部达标,0:存在未达标,*:未执行","level":"#map:$pr_lgtm_pass:1:success,0:error,*:na"}],"failNote":"#tpl:第 1-3 层平台默认满足（基线 8 分）；第 4 层未满足，第 5 层不再判定。当前得分 {score} 分","failEmptyText":"满分 10 分：5 层全部满足；第 4-5 层 rebot.yaml 配置 lgtm_need_num=2 且近 30 个已合入 PR 均有 2 名及以上审查者认可","dataNote":"指标定义采用 5 层递进计分（上一层全部满足才进入下一层），结合平台实际映射：第 1-3 层由 GitCode 平台默认分支保护满足（基线 8 分）；第 4-5 层考察 .infra_self_service/rebot.yaml 2 名及以上审查者配置与落实（+2 分），第 5 层与第 4 层同判——第 4 层不满足时第 5 层显示「未评估」。达标口径：近 30 个已合入 PR 每个都有 2 名及以上不同审查者（剔除机器人与 PR 作者）的 /lgtm。数据来源：P1 扫描 rebot.yaml + /lgtm 评论。","emptyHint":"该仓库暂无分支保护扫描数据","failItems":[{"when":"has_rebot_yaml=0","title":"第 4 层未满足：未启用 2 名及以上审查者","fields":[{"label":"检查层","value":"第 4 层（要求 2 名及以上审查者）"},{"label":"rebot.yaml","value":"未配置","level":"error"},{"label":"第 5 层","value":"未评估","level":"na"},{"label":"提升建议","value":"配置 .infra_self_service/rebot.yaml 并设置 lgtm_need_num=2"}],"reason":"未检出 .infra_self_service/rebot.yaml，第 4 层不满足，第 5 层不再判定 → 得分 3+3+2 = 8","searchText":"rebot.yaml 未配置 2名及以上审查者 第4层 未评估"},{"when":"has_rebot_yaml=1 && lgtm_need_num!=2","title":"第 4 层未满足：审查者人数要求未配置为 2 人","fields":[{"label":"检查层","value":"第 4 层（要求 2 名及以上审查者）"},{"label":"rebot.yaml","value":"已配置","level":"success"},{"label":"审查者人数要求","value":"#ifnull:$lgtm_need_num:—","level":"error"},{"label":"第 5 层","value":"未评估","level":"na"},{"label":"提升建议","value":"将 rebot.yaml 的 lgtm_need_num 设置为 2"}],"reason":"已配置 rebot.yaml 但 lgtm_need_num≠2，不触发 2 名及以上审查者检查，第 5 层不再判定 → 得分 8","searchText":"lgtm_need_num 审查者人数要求 第4层 未评估"},{"when":"pr_lgtm_pass=0","title":"第 4 层未满足：存在审查者未达标的已合入 PR","fields":[{"label":"检查层","value":"第 4 层（要求 2 名及以上审查者）"},{"label":"rebot.yaml","value":"已配置（lgtm_need_num=2）","level":"success"},{"label":"PR 审查达标","value":"存在未达标","level":"error"},{"label":"达标要求","value":"每个已合入 PR 有 2 名及以上审查者（剔机器人/作者）认可"},{"label":"第 5 层","value":"未评估","level":"na"}],"reason":"已配置 2 名及以上审查者，但近 30 个已合入 PR 中存在未达标 PR，第 5 层不再判定 → 得分 8","searchText":"审查者未达标 PR 第4层 未评估"}],"groups":[{"key":"tier","label":"层级递进判定","columns":[{"label":"层级","key":"lvl","type":"text"},{"label":"检查项","key":"items","type":"text"},{"label":"层级分值","key":"pts","type":"number"},{"label":"判定结果","key":"res","type":"text"},{"label":"判定依据","key":"basis","type":"text"}],"rows":[{"lvl":"第 1 层","items":"禁止删除分支、禁止强制推送","pts":"3","res":"满足","basis":"GitCode 平台默认分支保护（平台级管控，逐仓恒满足）"},{"lvl":"第 2 层","items":"要求 1 名以上审查者、要求通过 PR 合并、要求分支保持最新、要求最近推送审批","pts":"3","res":"满足","basis":"GitCode 平台默认分支保护（平台级管控，逐仓恒满足）"},{"lvl":"第 3 层","items":"要求 CI 状态检查通过","pts":"2","res":"满足","basis":"GitCode 平台默认分支保护（平台级管控，逐仓恒满足）"},{"lvl":"第 4 层","items":"要求 2 名以上审查者、要求 CODEOWNERS 审查","pts":"1","res":"#map:$pr_lgtm_pass:1:满足,*:不满足","basis":"#map:$pr_lgtm_pass:1:rebot.yaml 配置 lgtm_need_num=2，近 30 个已合入 PR 全部达标,*:未启用 2 名及以上审查者（未配置 rebot.yaml 或 lgtm_need_num≠2）"},{"lvl":"第 5 层","items":"取消过时审查、管理员强制执行保护规则","pts":"1","res":"#map:$pr_lgtm_pass:1:满足,*:未评估","basis":"#map:$pr_lgtm_pass:1:与第 4 层同判：2 名及以上审查者落实即视为满足,*:层级递进：第 4 层未满足，本层不再判定"}],"rowLevel":"#map:$res:不满足:error","cellOf":{"lvl":{"text":"$lvl"},"items":{"text":"$items"},"pts":{"text":"$pts"},"res":{"text":"$res","level":"#map:$res:满足:success,不满足:error,未评估:na"},"basis":{"text":"$basis"}},"searchText":"#tpl:{lvl} {items} {res} {basis}"},{"key":"prs","label":"近 30 PR lgtm 审批明细","columns":[{"label":"PR 号","key":"num","type":"number"},{"label":"lgtm 数","key":"cnt","type":"number"},{"label":"评审人数","key":"distinct","type":"number"},{"label":"是否达标","key":"pass","type":"text"},{"label":"审批人","key":"authors","type":"text"}],"rowsFrom":"$pr_lgtm_detail","cellOf":{"num":{"text":"#tpl:#{pr_number}","href":"#href:https://gitcode.com/{repoPath}/merge_requests/{pr_number}"},"cnt":{"text":"$lgtm_count"},"distinct":{"text":"$distinct_author"},"pass":{"text":"#bool:$pass:达标:未达标","level":"#bool:$pass:success:error"},"authors":{"text":"#join:$lgtms:login:、"}},"searchText":"#tpl:{pr_number} {lgtm_count}"}]}',
    updated_by = 'ai-assisted',
    updated_at = NOW()
WHERE metric_code = 'BRANCH_PROTECTION';
